    <style>
        .quick-stock-form{display:grid;grid-template-columns:170px minmax(280px,1fr) 220px 260px 140px;gap:14px;align-items:start;padding-bottom:30px}.quick-stock-form label{position:relative;display:grid;grid-template-rows:18px 46px;gap:7px;min-width:0;color:#52525b;font-size:11px;font-weight:700;letter-spacing:.04em;text-transform:uppercase}.quick-stock-form label>span:first-child{display:flex;align-items:end;white-space:nowrap}.quick-stock-form input{width:100%;height:46px;min-height:46px}.quick-stock-form .btn{width:100%;height:46px;min-height:46px;margin-top:25px;white-space:nowrap}.quick-stock-form small{position:absolute;top:74px;left:0;min-height:17px;color:#6b7280;font-size:11px;font-weight:500;letter-spacing:0;text-transform:none;white-space:nowrap}.quantity-input{display:flex;width:100%;height:46px;min-width:0}.quantity-input input{min-width:0;flex:1}.quantity-input>span{flex:0 0 auto;min-width:70px;max-width:110px;padding:0 10px;display:grid;place-items:center;border:1px solid #d4d4d8;border-left:0;background:#fafafa;color:#52525b;font-size:11px;font-weight:650;letter-spacing:0;text-transform:none;white-space:nowrap}.quick-entry-message{color:#166534;background:#f0fdf4;border-top:1px solid #bbf7d0}@media(max-width:1250px){.quick-stock-form{grid-template-columns:170px minmax(260px,1fr) 220px}.stock-cost{grid-column:2}.quick-stock-form .btn{grid-column:3;margin-top:25px}}@media(max-width:760px){.quick-stock-form{grid-template-columns:1fr 1fr;padding-bottom:34px}.stock-name{grid-column:1/-1}.stock-cost{grid-column:auto}.quick-stock-form .btn{grid-column:auto}}@media(max-width:520px){.quick-stock-form{grid-template-columns:1fr;gap:17px;padding-bottom:18px}.stock-name,.stock-cost,.quick-stock-form .btn{grid-column:auto}.quick-stock-form .btn{margin-top:0}.quick-stock-form small{position:static;margin-top:-2px;white-space:normal}.stock-cost{grid-template-rows:18px 46px auto}}
