    <script>
    (()=>{const form=document.querySelector('[data-quick-food-stock]');if(!form)return;const ingredients=@json($ingredients->mapWithKeys(fn($ingredient)=>[$ingredient->name=>['unit'=>$ingredient->purchase_unit,'base_unit'=>$ingredient->base_unit,'factor'=>(float)$ingredient->purchase_to_base]]));const name=form.elements.ingredient_name,quantity=form.elements.quantity,rate=form.elements.purchase_rate,unit=form.querySelector('[data-purchase-unit]'),rateUnit=form.querySelector('[data-rate-unit]'),total=form.querySelector('[data-total-cost]'),message=document.querySelector('[data-quick-entry-message]');const update=()=>{const purchaseUnit=ingredients[name.value]?.unit||'unit';unit.textContent=purchaseUnit;rateUnit.textContent='per '+purchaseUnit;const price=Number(rate.value),count=Number(quantity.value);total.textContent=count>0&&Number.isFinite(price)?`Total purchase cost: ₹${(price*count).toFixed(2)}`:'';};[name,quantity,rate].forEach(input=>input.addEventListener('input',update));form.addEventListener('submit',async event=>{event.preventDefault();if(!form.reportValidity())return;const button=form.querySelector('button');button.disabled=true;try{const response=await fetch(form.action,{method:'POST',headers:{Accept:'application/json','X-CSRF-TOKEN':form.querySelector('[name=_token]').value},body:new FormData(form)});const body=await response.json();if(!response.ok)throw new Error(Object.values(body.errors||{}).flat()[0]||body.message||'Stock could not be added.');message.hidden=false;message.textContent='✓ '+body.message;window.notify?.({title:'Stock added',message:body.message});name.value='';quantity.value='';rate.value='';unit.textContent='unit';rateUnit.textContent='per unit';total.textContent='';name.focus();}catch(error){window.notify?.({type:'error',message:error.message});}finally{button.disabled=false;}});update();})();
    </script>
